import numpy as np
def softmax(x):
    x = np.asarray(x, dtype=float)
    x = x - x.max(axis=-1, keepdims=True)
    e = np.exp(x)
    return e / e.sum(axis=-1, keepdims=True)

import numpy as np
def normalize(x):
    x = np.asarray(x, dtype=float)
    mn, mx = x.min(), x.max()
    rng = mx - mn
    if rng == 0:
        return np.zeros_like(x)
    return (x - mn) / rng

